import os
from pathlib import Path
from typing import List, Dict

from langchain_ollama import OllamaEmbeddings
from langchain_chroma import Chroma
from langchain_core.documents import Document

from .config import Config
from .preprocess import CHUNKS_PATH


def _load_chunks() -> List[Dict]:
    """Load chunk records from the JSONL file generated by preprocessing."""
    chunks = []
    with CHUNKS_PATH.open("r", encoding="utf-8") as f:
        for line in f:
            if line.strip():
                chunks.append(eval(line.strip()))  # safe because file is generated by us
    return chunks


def build_vectorstore(force: bool = False):
    """Create (or recreate) a persistent Chroma collection of the document chunks.

    * Uses the Ollama embedding model defined in Config.
    * Stores embeddings in ``Config.CHROMA_PERSIST_DIR`` under the collection name.
    * Batches documents according to ``Config.EMBEDDING_BATCH_SIZE``.
    """
    persist_dir = Path(Config.CHROMA_PERSIST_DIR)
    persist_dir.mkdir(parents=True, exist_ok=True)

    if force and persist_dir.exists():
        # Clear existing ChromaDB directory to allow fresh rebuild
        import shutil
        for child in persist_dir.iterdir():
            if child.is_file():
                child.unlink()
            else:
                shutil.rmtree(child)
        print(f"🗑️  Force flag: cleared existing ChromaDB at {persist_dir}")

    if not force and any(persist_dir.iterdir()):
        print(f"✅ Existing ChromaDB found at {persist_dir}, skipping rebuild.")
        return

    print("🔧 Building ChromaDB vectorstore…")
    embedding = OllamaEmbeddings(base_url=Config.OLLAMA_BASE_URL, model=Config.OLLAMA_EMBEDDING_MODEL)

    # Initialize empty collection (will be created on first add)
    vectorstore = Chroma(
        persist_directory=str(persist_dir),
        embedding_function=embedding,
        collection_name=Config.CHROMA_COLLECTION_NAME,
    )

    chunks = _load_chunks()
    print(f"📦 Loading {len(chunks)} chunks for indexing.")

    # Convert to Document objects with metadata
    docs: List[Document] = []
    for ch in chunks:
        docs.append(
            Document(
                page_content=ch["content"],
                metadata={
                    "title": ch.get("title"),
                    **ch.get("metadata", {}),
                },
            )
        )

    batch_size = Config.EMBEDDING_BATCH_SIZE
    for i in range(0, len(docs), batch_size):
        batch = docs[i : i + batch_size]
        vectorstore.add_documents(batch)
        print(f"✅ Indexed batch {i // batch_size + 1}/{(len(docs) - 1) // batch_size + 1}")

    # Persist the collection if the API provides a persist method
    if hasattr(vectorstore, "persist"):
        vectorstore.persist()
    else:
        # Fallback for newer langchain-chroma where the underlying client handles persistence
        try:
            vectorstore._client.persist()
        except Exception as e:
            print(f"⚠️ Persistence step failed: {e}")
    print(f"🎉 ChromaDB persisted at {persist_dir} (collection '{Config.CHROMA_COLLECTION_NAME}').")
